<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {BookOpen,GitCommitHorizontal,History,LoaderCircle,Pencil,Save} from 'lucide-vue-next';
import type {RepositoryReadmeState,RepositoryReadmeHistory,RepositoryReadmeDiff} from '@oxen/shared';
import {request,queryString} from '../api';
import {useAppStore} from '../stores/app';
import {createDatasetUiStateClient,type DatasetUiStateClient} from '../dataset-ui-state-client';
import {persistStableForm} from '../stable-form-checkpoint';
import SafeMarkdown from './SafeMarkdown.vue';
import TextDiff from './TextDiff.vue';
const props=defineProps<{base:string;branch:string}>(),emit=defineEmits<{saved:[commitId:string]}>(),app=useAppStore();
const state=ref<RepositoryReadmeState>(),content=ref(''),message=ref('更新数据集说明'),editing=ref(false),mode=ref<'edit'|'preview'|'diff'>('edit'),loading=ref(false),busy=ref(false),error=ref(''),checkpointError=ref(''),retained=ref(false),recovery=ref<{content:string;message:string;baseContent:string}>(),history=ref<RepositoryReadmeHistory>(),historical=ref<RepositoryReadmeDiff>(),historyLoading=ref(false),historyOpen=ref(false);
let generation=0,client:DatasetUiStateClient|undefined,timer:ReturnType<typeof setTimeout>|undefined,storedSignature='',ready=false;
const dirty=computed(()=>!!state.value&&content.value!==state.value.content),payload=computed(()=>state.value?{version:1,baseContent:state.value.content,content:content.value,message:message.value,editing:editing.value}:undefined),signature=computed(()=>JSON.stringify(payload.value)),principal=computed(()=>app.status?.identity?.kind+':'+app.status?.identity?.id),context=()=>props.base+':'+props.branch+':'+principal.value;
async function load(){const current=++generation;clearTimeout(timer);ready=false;loading.value=true;error.value='';checkpointError.value='';state.value=undefined;editing.value=false;recovery.value=undefined;historyOpen.value=false;history.value=undefined;historical.value=undefined;client=createDatasetUiStateClient({base:props.base,ref:props.branch,kind:'readme',context});try{const value=await request<RepositoryReadmeState>(props.base+'/readme'+queryString({ref:props.branch}));if(current!==generation)return;state.value=value;content.value=value.content;message.value='更新数据集说明';if(app.status?.authenticated){const checkpoint=await client.load();if(current!==generation)return;retained.value=!!checkpoint;if(checkpoint){const raw=checkpoint.payload;if(!raw||typeof raw!=='object'||Array.isArray(raw)||raw.version!==1||typeof raw.content!=='string'||typeof raw.baseContent!=='string'||typeof raw.message!=='string')throw new Error('已保留的说明输入格式无法识别，未覆盖当前说明。');const form={content:raw.content,message:raw.message,baseContent:raw.baseContent};if(raw.baseContent===value.content){content.value=form.content;message.value=form.message;editing.value=raw.editing===true||form.content!==value.content;}else recovery.value=form;}}storedSignature=signature.value;ready=true;}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function persist(){clearTimeout(timer);if(!state.value)return true;if(!ready||!client)return !dirty.value;if(recovery.value)return true;if(!app.status?.authenticated||signature.value===storedSignature)return true;if(!state.value.canEdit&&!retained.value)return !dirty.value;const current=generation,captured=signature.value;try{await client.save(payload.value,state.value.commitId);if(current!==generation)return false;storedSignature=captured;retained.value=true;checkpointError.value='';return true;}catch(cause){checkpointError.value='说明输入尚未保留：'+(cause as Error).message;return false;}}
async function mayLeave(){if(busy.value)return false;return persistStableForm({generation:()=>generation,signature:()=>signature.value,persist,settle:nextTick});}
async function save(){if(!state.value?.canEdit||!dirty.value||!message.value.trim()||busy.value||recovery.value)return;busy.value=true;error.value='';try{if(!await persist())return;const value=await request<RepositoryReadmeState>(props.base+'/readme',{method:'PUT',body:JSON.stringify({ref:props.branch,expectedCommit:state.value.commitId,content:content.value,message:message.value.trim()})});state.value=value;content.value=value.content;editing.value=false;try{await client?.remove();retained.value=false;}catch(cause){app.notify('说明已提交；清理本机保留输入失败，可重新读取核对。');}storedSignature=signature.value;emit('saved',value.commitId);app.notify('数据集说明已提交到当前分支。');}catch(cause){error.value=(cause as Error).message;await persist();}finally{busy.value=false;}}
async function openHistory(page=1){if(!state.value)return;const current=generation;historyOpen.value=true;historyLoading.value=true;error.value='';try{const value=await request<RepositoryReadmeHistory>(props.base+'/readme/history'+queryString({ref:state.value.commitId,page}));if(current===generation){history.value=value;historical.value=undefined;}}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)historyLoading.value=false;}}
async function inspect(commitId:string){if(!state.value)return;const current=generation;historyLoading.value=true;try{const value=await request<RepositoryReadmeDiff>(props.base+'/readme/diff'+queryString({ref:state.value.commitId,commit:commitId}));if(current===generation)historical.value=value;}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)historyLoading.value=false;}}
async function refresh(){if(await mayLeave())await load();}
async function restore(){if(!recovery.value||!state.value)return;const form=recovery.value;if(!await app.confirmAction('最新说明已变化。将保留的输入放入编辑器，由你核对差异；尚不提交到项目。',{title:'恢复说明输入',confirmLabel:'恢复并核对'}))return;content.value=form.content;message.value=form.message;editing.value=true;mode.value='diff';recovery.value=undefined;storedSignature='';await persist();}
function beforeUnload(event:BeforeUnloadEvent){if(busy.value||signature.value!==storedSignature&&dirty.value){event.preventDefault();event.returnValue='';}}
const unregister=app.registerDraftGuard(mayLeave);onBeforeRouteLeave(mayLeave);onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath||mayLeave());window.addEventListener('beforeunload',beforeUnload);
watch(()=>[props.base,props.branch,principal.value],load,{immediate:true});watch(signature,()=>{if(ready&&app.status?.authenticated&&(dirty.value||retained.value)){clearTimeout(timer);timer=setTimeout(()=>void persist(),650);}});
onBeforeUnmount(()=>{generation++;clearTimeout(timer);unregister();window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template><section class="panel readme-panel"><header><span><BookOpen :size="17"/>数据集说明</span><div><code v-if="state"><GitCommitHorizontal :size="13"/>{{state.commitId.slice(0,10)}}</code><button class="btn btn-ghost" :disabled="loading||busy" @click="openHistory()"><History :size="14"/>历史</button><button v-if="state?.canEdit" class="btn" :disabled="busy||!!recovery||!ready" @click="editing=!editing"><Pencil :size="14"/>{{editing?'返回阅读':'编辑说明'}}</button></div></header>
<p v-if="loading" class="readme-state" role="status"><LoaderCircle class="spin" :size="18"/>读取项目说明…</p><p v-if="error" class="error-state" role="alert">{{error}}<button class="btn" :disabled="busy" @click="refresh">重新读取并恢复本机输入</button></p><p v-if="checkpointError" class="error-state" role="alert">{{checkpointError}}<button class="btn" @click="persist">重试保留</button></p>
<div v-if="recovery&&state" class="readme-recovery"><strong>有先前保留的说明输入，最新说明也已有变化。</strong><TextDiff :before="state.content" :after="recovery.content" :path="state.path"/><button class="btn" @click="restore">恢复输入并核对</button></div>
<template v-if="state&&!loading"><div v-if="editing" class="readme-editor"><nav><button v-for="item in (['edit','preview','diff'] as const)" :key="item" class="btn" :aria-pressed="mode===item" @click="mode=item">{{{edit:'编辑 Markdown',preview:'预览',diff:'核对修改'}[item]}}</button><span>{{retained?'输入已在本机保留':'输入尚未提交'}}</span></nav><textarea v-if="mode==='edit'" v-model="content" rows="18" maxlength="2097152" spellcheck="false" aria-label="数据集说明 Markdown" :disabled="busy||!state.canEdit"/><SafeMarkdown v-else-if="mode==='preview'" :source="content"/><TextDiff v-else :before="state.content" :after="content" :path="state.path"/><footer><label class="field">提交说明<input v-model="message" maxlength="4000" :disabled="busy"/></label><button class="btn btn-primary" :disabled="busy||!state.canEdit||!dirty||!message.trim()" @click="save"><LoaderCircle v-if="busy" class="spin" :size="15"/><Save v-else :size="15"/>提交说明修改</button></footer></div><div v-else class="readme-body"><SafeMarkdown v-if="state.content.trim()" :source="state.content"/><div v-else class="empty"><BookOpen :size="26"/><h3>尚未填写数据集说明</h3><p>补充用途、来源、许可、字段与标注指南。</p><button v-if="state.canEdit" class="btn" @click="editing=true">编写 README</button></div></div></template>
<section v-if="historyOpen" class="readme-history"><header><h4>README 修改历史</h4><button class="btn btn-ghost" @click="historyOpen=false">收起</button></header><p v-if="historyLoading" role="status">读取固定版本历史…</p><template v-if="history"><button v-for="item in history.items" :key="item.id" class="readme-history-item" @click="inspect(item.id)"><span><strong>{{item.message}}</strong><small>{{item.author}} · {{new Date(item.timestamp).toLocaleString('zh-CN')}}</small></span><code>{{item.id.slice(0,10)}}</code></button><p v-if="!history.items.length" class="readme-state">这一页提交未修改当前 README。</p><div class="history-pages"><button class="btn" :disabled="history.page===1||historyLoading" @click="openHistory(history.page-1)">上一页提交</button><button class="btn" :disabled="!history.hasMore||historyLoading" @click="openHistory(history.page+1)">下一页提交</button></div></template><TextDiff v-if="historical" :before="historical.before" :after="historical.after" :path="historical.path"/></section></section></template>
<style scoped>.readme-panel{padding:0;overflow:hidden}.readme-panel>header,.readme-history>header{padding:14px 20px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.readme-panel header>span,.readme-panel header>div,.readme-panel code{display:flex;align-items:center;gap:7px}.readme-panel header{font-size:13px}.readme-panel code{font:11px var(--font-mono,monospace);color:var(--muted)}.readme-panel .btn{font-size:12px}.readme-body{padding:26px;min-height:300px}.readme-state{display:flex;align-items:center;gap:9px;padding:20px;font-size:13px;color:var(--muted)}.readme-editor{padding:20px}.readme-editor nav{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}.readme-editor nav .btn[aria-pressed=true]{color:var(--primary);background:var(--primary-soft)}.readme-editor nav span{font-size:11px;color:var(--muted);margin-left:auto}.readme-editor>textarea{width:100%;box-sizing:border-box;resize:vertical;min-height:350px;padding:16px;background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:6px;font:13px/1.8 var(--font-mono,monospace)}.readme-editor footer{display:flex;justify-content:space-between;align-items:flex-end;gap:15px;border-top:1px solid var(--line);margin-top:18px;padding-top:18px}.readme-editor footer label{margin:0;flex:1}.readme-history{border-top:1px solid var(--line)}.readme-history-item{display:flex;text-align:left;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);width:100%;padding:14px 20px}.readme-history-item strong{font-size:13px;font-weight:500}.readme-history-item small{display:block;font-size:11px;color:var(--muted);margin-top:7px}.history-pages{padding:14px;display:flex;justify-content:flex-end;gap:10px}.readme-recovery{padding:18px;background:var(--surface-raised);font-size:13px}.readme-recovery .btn{margin-top:14px}.readme-panel>.error-state{margin:15px}@media(max-width:600px){.readme-body,.readme-editor{padding:16px}.readme-editor footer{flex-direction:column;align-items:stretch}.readme-editor nav span{margin-left:0}.readme-panel>header{padding:14px}}</style>
